head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > editFormat]<br/>inputType='text' 인 Column 에 값을 입력중이거나 값이 표시될때 적용할 포맷을 마스크 문자로 설정합니다.",
    "validation" : [
        "'||' 설정 시, 한 개 이상의 포맷을 정의할 때 포맷의 구분자로 사용하는 특수 기호입니다.",
        "'{,}' 설정 시, 특정 범위(여러개 가능)의 입력 문자를 editDisplayChar 속성값으로 마스킹 처리하기 위한 특수 기호입니다.",
        "'!' 설정 시, 마스크 문자와 특수 기호를 이스케이프 처리하는 특수 기호입니다.",
        "'{,}' 기호로 마스킹 처리된 범위에 일반 문자가 있는 경우 해당 문자는 마스킹 되지 않고 그대로 표시됩니다.",
        "'||' 기호로 다중 포맷을 설정했을때 마스크 문자의 갯수가 동일한 포맷이 있는 경우 먼저 정의한 포맷이 사용됩니다.",
        "'||' 기호로 다중 포맷을 설정했을때 editPlaceholderChar 속성을 설정하면 마스크 문자의 갯수가 제일 많은 포맷이 표시됩니다.",
        "'||' 기호로 다중 포맷을 설정했을때 editPlaceholderChar 속성을 설정하면 마스크 문자의 갯수가 동일한 포맷이 있는 경우 마지막에 정의한 포맷이 표시됩니다.",
    ]
}



scwin.gVar = {
    // editFormat 별 Row 바인딩 값 (다중 포맷은 포맷별 자리수의 값을 Row 마다 둔다)
    "rowValues" : {
        "##-###-####||###-###-####||###-####-####" : ["021231234", "0311231234", "01012341234"],
        "###-####-####||##-###-####||###-###-####" : ["021231234", "0311231234", "01012341234"],
        "###-####||####-###" : ["1234567"],
        "######-#{######}" : ["9001011234567"],
        "####-{####}-{####}-####" : ["1234567812345678"],
        "###{-####-}####" : ["01012345678"],
        "!A-####" : ["1234"],
        "!{####!}" : ["1234"]
    },
    // 편집 중 입력창 값 기록 (셀 더블클릭 시 초기화)
    "editRow" : -1,
    "editValue" : []
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_editFormat.setValue("##-###-####||###-###-####||###-####-####");
    con_editDisplayChar.setValue("*");
    con_editPlaceholderChar.setValue("");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - raw : 원본값 Column (readOnly)
//  - val : 검증 대상 Column (inputType=text, editFormat / editDisplayChar / editPlaceholderChar 를 옵션값으로 설정)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }
    scwin.gVar.editRow = -1;
    scwin.gVar.editValue = [];

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 다중 포맷은 Row 마다 포맷별 자리수(9 / 10 / 11 자리)의 값이 바인딩됨\n[절차] 조건 선택 -> Target 재생성 -> 셀 표시값 확인\n[절차] 결과창 clear -> val 셀 더블클릭 -> 원본값과 같은 자리수의 숫자를 한 자씩 입력 (기존 값은 대체됨) -> 셀 밖 클릭으로 포커스 해제 -> 셀 표시값 확인\n[확인] 입력 자리수별 입력창 값으로 선택된 포맷 확인, 편집 상태가 아닐때의 셀 표시값과 DataList 값 비교"', '', 'label1');

    let cEditFormat = con_editFormat.getValue();
    let cEditDisplayChar = con_editDisplayChar.getValue();
    let cEditPlaceholderChar = con_editPlaceholderChar.getValue();
    let arrValue = scwin.gVar.rowValues[cEditFormat] || [];

    // dataList 생성 (body column id 와 동일한 컬럼 id 사용)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="raw" name="raw" dataType="text"></w2:column>';
    strDlt += '<w2:column id="val" name="val" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    let arrData = [];
    for (let i = 0; i < arrValue.length; i++) {
        arrData.push({ "raw" : arrValue[i], "val" : arrValue[i] });
    }
    dlt_bind.setJSON(arrData, false);

    // val Column 속성 (미설정 옵션은 속성 자체를 넣지 않는다)
    let attrVal = ' inputType="text" dataType="text" editFormat="' + cEditFormat + '"';
    if (cEditDisplayChar !== '') {
        attrVal += ' editDisplayChar="' + cEditDisplayChar + '"';
    }
    if (cEditPlaceholderChar !== '') {
        attrVal += ' editPlaceholderChar="' + cEditPlaceholderChar + '"';
    }

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:560px;height:160px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="column1" value="원본값"></w2:column>';
    strTarget += '<w2:column width="380" style="" inputType="text" id="column2" value="val"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="raw" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="380" style="" id="val" value=""' + attrVal + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 편집 입력창 값 기록
    //  - 셀 더블클릭(편집 진입) 시 기록을 초기화하고 편집 진입 직후 입력창 값을 첫 값으로 기록
    //  - 키를 뗄 때마다 입력창 값 기록
    target1.render.addEventListener("dblclick", function () {
        scwin.gVar.editValue = [];
        setTimeout(function () {
            scwin.gVar.editRow = target1.getFocusedRowIndex();
            let elem = document.activeElement;
            if (elem && elem.tagName === "INPUT" && target1.render.contains(elem)) {
                scwin.gVar.editValue.push(elem.value);
            }
        }, 0);
    }, true);
    target1.render.addEventListener("keyup", scwin.recordEditValue, true);
}



// 편집 중 키를 뗄 때마다 입력창 값을 기록 (입력창의 포맷 처리가 끝난 뒤의 값을 읽는다)
scwin.recordEditValue = function (e) {
    let elem = e.target;
    if (!elem || elem.tagName !== "INPUT") {
        return;
    }
    setTimeout(function () {
        let arr = scwin.gVar.editValue;
        if (arr.length === 0 || arr[arr.length - 1] !== elem.value) {
            arr.push(elem.value);
        }
    }, 0);
}



// val 셀의 화면 표시값
scwin.getCellText = function (rowIndex) {
    let td = document.querySelector("td[id*='" + target1.id + "_cell_" + rowIndex + "_1']");
    return td ? td.textContent : "";
}



// 설정 조건, Row 별 DataList 값 -> 셀 표시값, 편집 중 입력창 값 출력
//  - validation 1 : 다중 포맷에서 Row (9 / 10 / 11 자리) 별 셀 표시값과 입력 자리수별 입력창 값
//  - validation 2 : {,} 범위(1개 / 2개)의 editDisplayChar 마스킹 셀 표시값
//  - validation 3 : ! 로 이스케이프한 마스크 문자(A) / 특수 기호({,}) 의 셀 표시값
//  - validation 4 : {,} 범위 안 일반 문자(-) 의 셀 표시값
//  - validation 5 : 마스크 문자 갯수가 같은 포맷에서 입력창 값과 셀 표시값
//  - validation 6, 7 : editPlaceholderChar 설정 시 셀 표시값과 입력창 값
scwin.btn_checkCell_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let cEditDisplayChar = con_editDisplayChar.getValue();
    let cEditPlaceholderChar = con_editPlaceholderChar.getValue();

    let arrCond = ["editFormat : " + con_editFormat.getValue()];
    if (cEditDisplayChar !== '') {
        arrCond.push("editDisplayChar : " + cEditDisplayChar);
    }
    if (cEditPlaceholderChar !== '') {
        arrCond.push("editPlaceholderChar : " + cEditPlaceholderChar);
    }
    bottom.setReturnValue(arrCond.join(" / "));

    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        bottom.setReturnValue("Row " + i + " DataList 값 : " + dlt_bind.getCellData(i, "val") + " -> 셀 표시값 : " + scwin.getCellText(i));
    }

    // 편집하지 않았으면 편집 줄은 출력하지 않는다
    if (scwin.gVar.editRow < 0 || scwin.gVar.editValue.length === 0) {
        return;
    }
    bottom.setReturnValue("Row " + scwin.gVar.editRow + " 편집 중 입력창 값 : " + scwin.gVar.editValue.join(" > "));
}
